    """Return the expected flattened list from the scorer cache."""
    with open("scorer_cache/expected_flatten.json", "r") as f:
        return json.load(f)

def second_largest(nums: list) -> int:
    """Return the second largest distinct value; raise ValueError if there is none."""
    # Use a set to get distinct values
    distinct = set(nums)
    if len(distinct) < 2:
        raise ValueError("Not enough distinct values for second largest")
    # Find the largest and second largest by iterating once
    max1 = max2 = float('-inf')
    for v in distinct:
        if v > max1:
            max2, max1 = max1, v
        elif v > max2:
            max2 = v
    return max2
